mapper.select:
select t1.id,t1.book_id,t1.comment_content,t1.location,t1.reply_count,t1.like_count,t1.create_time,t2.username create_user_name,t2.user_photo create_user_photo from book_comment t1 inner join user t2 on t1.create_user_id = t2.id where t1.audit_status != 2
and t1.book_id = #{bookId}
and t1.create_user_id = #{userId}
order by (t1.like_count + t1.reply_count * 2) desc, t1.create_time desc
order by t1.create_time desc

mapper.update:
update book_comment
set reply_count = reply_count + 1
where id = #{commentId}

mapper.select:
select t1.id,t1.book_id,t1.index_id,t1.paragraph_id,t1.comment_content,t1.location,t1.reply_count,t1.like_count,t1.create_time, t2.username create_user_name,t2.user_photo create_user_photo from book_comment t1 inner join user t2 on t1.create_user_id = t2.id where t1.audit_status != 2 and t1.comment_type = 2
and t1.index_id = #{indexId}
and t1.paragraph_id = #{paragraphId}
order by t1.create_time desc
